SELECT R.NAME, RES.POINTS FROM RACES AS R INNER JOIN RESULTS AS RES ON R.RACEID = RES.RACEID INNER JOIN DRIVERS AS D ON RES.DRIVERID = D.DRIVERID WHERE D.FORENAME = 'LEWIS' AND D.SURNAME = 'HAMILTON' AND R.YEAR = (SELECT MIN(R2.YEAR) FROM RACES AS R2 INNER JOIN RESULTS AS RES2 ON R2.RACEID = RES2.RACEID INNER JOIN DRIVERS AS D2 ON RES2.DRIVERID = D2.DRIVERID WHERE D2.FORENAME = 'LEWIS' AND D2.SURNAME = 'HAMILTON') ORDER BY R.DATE LIMIT 1;
-- ----------sql2------------
-- 2147483648, 645
SELECT T1.NAME, T2.POINTS FROM RACES AS T1 INNER JOIN DRIVERSTANDINGS AS T2 ON T2.RACEID = T1.RACEID INNER JOIN DRIVERS AS T3 ON T3.DRIVERID = T2.DRIVERID WHERE T3.FORENAME = 'LEWIS' AND T3.SURNAME = 'HAMILTON' ORDER BY T1.YEAR ASC LIMIT 1;

