-- ----------sql1------------
-- 2147483649
SELECT T2.NAME FROM (SELECT LEAGUE_ID, SUM(HOME_TEAM_GOAL + AWAY_TEAM_GOAL) AS LEAGUE_TOTAL_GOALS FROM MATCH WHERE SEASON = '2015/2016' GROUP BY LEAGUE_ID) AS T1 INNER JOIN LEAGUE AS T2 ON T1.LEAGUE_ID = T2.ID ORDER BY T1.LEAGUE_TOTAL_GOALS DESC LIMIT 1;
-- ----------sql2------------
-- 2147483650
SELECT T2.NAME FROM MATCH AS T1 INNER JOIN LEAGUE AS T2 ON T1.LEAGUE_ID = T2.ID WHERE T1.SEASON = '2015/2016' GROUP BY T2.NAME ORDER BY SUM(T1.HOME_TEAM_GOAL + T1.AWAY_TEAM_GOAL) DESC LIMIT 1;

